    {
      "rank": 1,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "The detection of high-energy astrophysical neutrinos opened a new observational window on the universe and established neutrino astronomy as a field.",
        "attribution": "Halzen's scientific leadership and Karle's major role in developing and building IceCube make a focused experimental attribution credible.",
        "maturity": "The astrophysical flux is supported by a substantial body of observations, though identifying individual sources remains in progress.",
        "uncertainties": [
          "The origin of much of the diffuse neutrino flux is still uncertain."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Heino Falcke",
        "James M. Moran",
        "Sheperd S. Doeleman"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale black-hole imaging is a striking technical achievement and a new way to test gravity in the strong-field regime.",
        "attribution": "Falcke's theoretical work on the black-hole shadow, Moran's contributions to very-long-baseline interferometry, and Doeleman's leadership in realizing the observations represent distinct contributions.",
        "maturity": "The M87 and Sagittarius A* results have established the method and produced images consistent with general relativity.",
        "uncertainties": [
          "The result depends on a large collaboration and complex image reconstruction, so individual attribution needs careful review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page Jr.",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background made precision cosmology possible and sharply constrained the universe's age, composition, and evolution.",
        "attribution": "Bennett and Page led central experimental and instrument efforts, while Spergel's cosmological interpretation helped establish the scientific reach of the measurements.",
        "maturity": "The results have been extensively tested and followed by independent measurements, with WMAP remaining a landmark dataset.",
        "uncertainties": [
          "The division of credit among WMAP leadership, instrument builders, and the broader collaboration requires expert assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical-lattice quantum simulation brought controlled many-body quantum systems into the laboratory and created a powerful route to study models that are difficult to solve.",
        "attribution": "Zoller's theoretical proposals and the experiments led by Greiner and Bloch form a compelling theory-and-experiment account, though the field's development involved many groups.",
        "maturity": "The approach has matured through sustained experimental progress and has become a widely used research platform.",
        "uncertainties": [
          "The precise boundary between this achievement and the broader development of ultracold quantum gases is not sharp."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Claudio Pellegrini",
        "Jörg Rossbach",
        "Kwang-Je Kim"
      ],
      "assessment": {
        "nobel_worthiness": "X-ray free-electron lasers provide extremely bright, short-pulse coherent X-rays and have transformed experiments on matter at atomic and molecular scales.",
        "attribution": "Pellegrini's source concept and accelerator and facility contributions associated with Rossbach and Kim are important, but the achievement spans a large international effort.",
        "maturity": "These facilities have operated for years and enabled a broad, durable body of science.",
        "uncertainties": [
          "The distinction between foundational invention, accelerator design, and facility realization complicates individual credit."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Nial R. Tanvir"
      ],
      "assessment": {
        "nobel_worthiness": "The multi-messenger observations of a neutron-star merger and its kilonova tied compact-object mergers to heavy-element production, a major advance in astrophysics.",
        "attribution": "Metzger's theoretical work, Kasen's modeling of kilonova emission, and Tanvir's observational contributions provide complementary links in the discovery.",
        "maturity": "The 2017 event gave strong confirmation of the kilonova picture, while the broader contribution of mergers to r-process elements remains under study.",
        "uncertainties": [
          "The relative contribution of neutron-star mergers and other sites to the cosmic abundance of heavy elements is unresolved."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Daniel J. Eisenstein",
        "John A. Peacock",
        "Shaun Cole"
      ],
      "assessment": {
        "nobel_worthiness": "Baryon acoustic oscillations provide a robust cosmological distance scale and a powerful probe of the universe's expansion history.",
        "attribution": "The credited researchers are associated with key early theoretical and observational work, but the method's development and measurement required many teams.",
        "maturity": "BAO measurements have been replicated across multiple surveys and are central to modern precision cosmology.",
        "uncertainties": [
          "Individual credit is difficult to separate from the broad survey collaborations and the wider development of large-scale-structure methods."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have advanced precision measurement to a level with consequences for fundamental tests, timekeeping, and future measurement networks.",
        "attribution": "Katori and Ye independently developed leading approaches, making the two-person attribution unusually clear.",
        "maturity": "The clocks are exceptionally mature as instruments, although their ultimate scientific and societal consequences are still unfolding.",
        "uncertainties": [
          "The case depends on whether the achievement is judged as a sufficiently fundamental physics discovery rather than a transformative measurement technology."
        ]
      }
    }
  ]
